(() => {
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),modal=document.getElementById('modalLayer');
const W=1000,H=650,saveKey='littleThingsSave_v1';
const state={started:false,location:'shop',player:{x:500,y:455},keys:{},near:null,clues:[],visited:['shop'],topics:{},memories:[],ending:null,decor:'fern',sound:true,dialogueCount:{},boardPick:null,progress:0};
const characters={
 Mara:{mark:'M',look:'A young woman in a rust-red coat, her dark curls still bright with rain.',tone:'Warm, thoughtful; she often finds the right question a moment late.',known:'Elias was my grandfather. I knew his garden hands, not his younger self.',history:'Mara found the watch in Elias’s writing desk after his death. She wants to understand him without turning him into a stranger.'},
 June:{mark:'J',look:'A silver-haired woman with a station-blue scarf and a very straight back.',tone:'Measured and exact; when she is moved, her sentences get shorter.',known:'I worked at Brackenford station. Elias and I meant to take the 8:17 together.',history:'June believed Elias left without her. She stayed in town, eventually making a life among timetables, gardens, and people who needed a steady hand.'},
 Theo:{mark:'T',look:'A lean clockmaker with brass spectacles, ink on one cuff, and a waistcoat full of tools.',tone:'Delighted by mechanism; speaks to clocks as if they are shy animals.',known:'The watch has been kept carefully. Something is tucked behind its inner case.',history:'Theo learned repair from his aunt. He distrusts a clock that claims to be exact and likes every object with a second purpose.'},
 Rowan:{mark:'R',look:'Your neighbor, in a moss-green shawl, carrying a basket that always seems to contain a book.',tone:'Dryly kind, observant, and never in a hurry to finish a thought.',known:'A town is mostly people leaving little pieces of themselves in one another’s rooms.',history:'Rowan lives next door and has watched the street change for forty years. They know who has a spare key, and when to offer tea instead.'}
};
const places={shop:{name:'THE LITTLE THINGS · SHOP',floor:'#846b53'},street:{name:'LANTERN LANE · TOWN STREET',floor:'#586c68'},station:{name:'BRACKENFORD · OLD STATION',floor:'#697b76'},repair:{name:'THE CLOCK & CROW · REPAIR SHOP',floor:'#75634d'}};
const cluesData={watch:{title:'The stopped watch',glyph:'◷',short:'8:17 · For June. E.',desc:'A brass pocket watch, warm from being carried. The hands have stopped at 8:17. On the back: “For June. 8:17. E.” The minute hand catches slightly, as if it stopped under a small pressure.'},photo:{title:'The photograph',glyph:'▧',short:'Two young friends at the station',desc:'A sun-faded photograph of two young people on the station platform. On the back, in a familiar hand: “June says the 8:17 is lucky. —E.” The young man wears the same watch chain.'},timetable:{title:'The 8:17 timetable',glyph:'▤',short:'The last train out, on a wet Tuesday',desc:'An old station timetable. The 8:17 was the last train toward the coast. A pencilled note in its margin reads: “Platform 2. Don’t be late this time.” The paper is creased where someone kept it folded for years.'},mechanism:{title:'A careful repair',glyph:'⚙',short:'The case has been opened before',desc:'Theo found a narrow seam behind the watch’s inner case. The watch was not damaged: its hands were stopped by hand, and the back has been opened before. Something thin is hidden inside.'},letter:{title:'Elias’s unsent letter',glyph:'✉',short:'A letter folded behind the watch face',desc:'“June — Father took ill that afternoon. I could not leave him alone, not even for the length of one journey. I thought I would write tomorrow, when I had the words. Tomorrow became years. I kept your watch, and the place beside me on the train. I am sorry I let silence tell the story for me. —Elias.”'},choice:{title:'A quiet kindness',glyph:'✦',short:'The watch and letter found their way',desc:'The past cannot be changed. What can change is who carries it now.'}};
function save(){try{localStorage.setItem(saveKey,JSON.stringify({...state,keys:undefined,near:undefined,boardPick:undefined}));}catch(e){}}
function load(){try{const d=JSON.parse(localStorage.getItem(saveKey));if(d){Object.assign(state,d);state.keys={};state.started=true;return true}}catch(e){}return false}
function startNew(){Object.assign(state,{started:true,location:'shop',player:{x:500,y:455},clues:[],visited:['shop'],topics:{},memories:[],ending:null,decor:'fern',progress:0,dialogueCount:{}});save();closeModal();toast('A small beginning.');}
function closeModal(){modal.innerHTML='';}
function showMenu(){modal.innerHTML=`<div class="menu-card"><div class="menu-title">THE LITTLE<br>THINGS</div><div class="menu-subtitle">A STORY IN FOUR PLACES</div><p>A rain-soft mystery about a watch, a train that left, and the things we almost said.</p>${state.started?'<button class="action" data-act="resume">Continue your story</button>':''}<button class="action" data-act="new">${state.started?'Begin again':'Open the shop'}</button><button class="action secondary" data-act="settings">Settings & controls</button><div style="font-size:9px;color:#c5b895;margin-top:18px">WASD / arrows to wander · E to interact · J journal · B clue board</div></div>`;}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
function addClue(id){if(state.clues.includes(id))return;state.clues.push(id);state.progress++;save();document.getElementById('clueCount').textContent=state.clues.length;toast('A detail worth keeping · Journal updated');pulse=1;}
function setLoc(loc){state.location=loc;if(!state.visited.includes(loc))state.visited.push(loc);state.player={x:500,y:455};document.getElementById('locationName').textContent=places[loc].name;closeModal();save();toast(places[loc].name);}
function panel(content,wide=false){modal.innerHTML=`<div class="panel ${wide?'wide':''}"><button class="close" aria-label="Close">×</button>${content}</div>`;}
function journal(tab='Evidence'){
const tabs=['Evidence','People','Places','Notes'];let body='';
if(tab==='Evidence')body=state.clues.length?state.clues.map(id=>`<div class="entry"><strong>${cluesData[id].glyph} &nbsp;${cluesData[id].title}</strong><small>KEPT</small><p>${cluesData[id].short}</p></div>`).join(''):'<p>Your pockets are empty. Walk near something interesting and press <b>E</b> to take a closer look.</p>';
if(tab==='People')body=Object.entries(characters).map(([name,c])=>`<div class="entry"><strong>${name}</strong><small>${state.topics[name]?'MET':'NOT MET'}</small><p>${state.topics[name]?c.known:'Someone you may come across in Brackenford.'}</p></div>`).join('');
if(tab==='Places')body=Object.entries(places).map(([id,p])=>`<div class="entry"><strong>${p.name.split(' · ').pop()}</strong><small>${state.visited.includes(id)?'VISITED':'UNSEEN'}</small><p>${id==='shop'?'A snug room of found things and lamplight.':id==='street'?'The narrow lane between the shop and the station.':id==='station'?'An old platform where the 8:17 once waited.':'A repair shop that smells of oil, cedar, and tea.'}</p></div>`).join('');
if(tab==='Notes')body=`<div class="entry"><strong>The Watch That Waited</strong><small>${state.ending?'RESOLVED':state.clues.length>3?'NEAR THE HEART':'IN PROGRESS'}</small><p>${state.ending?'Some stories do not undo the years. They make room for a kinder telling.':`You have kept ${state.clues.length} of 5 pieces. A stopped watch, an old friendship, and a missed train.`}</p></div>${state.memories.map(x=>`<div class="entry"><strong>A remembered conversation</strong><p>${x}</p></div>`).join('')}`;
panel(`<div class="panel-kicker">A POCKET-SIZED RECORD</div><h2>The Journal</h2><p class="lead">Little details have a way of finding one another.</p><div class="tabs">${tabs.map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${body}<div class="btn-row"><button class="action secondary" data-act="board">Open clue board</button><button class="action secondary" data-act="inventory">Pocket inventory</button></div>`,true);
}
function inventory(){const have=state.clues.map(id=>cluesData[id]);panel(`<div class="panel-kicker">WHAT YOU’VE FOUND</div><h2>Your pockets</h2><p class="lead">A careful keeper makes room for small things.</p>${have.length?`<div class="grid">${have.map(c=>`<div class="card"><div class="glyph">${c.glyph}</div><strong>${c.title}</strong><small>${c.short}</small></div>`).join('')}</div>`:'<p>Nothing yet. The watch is waiting on the counter.</p>'}<div class="divider"></div><button class="action secondary" data-act="journal">Back to journal</button>`);
}

function board(){const have=state.clues.filter(x=>['photo','timetable','mechanism','letter','watch'].includes(x));let nodes=have.map(id=>`<button class="clue-node ${state.boardPick===id?'selected':''}" data-pick="${id}"><strong>${cluesData[id].glyph} ${cluesData[id].title}</strong><small>${cluesData[id].short}</small></button>`).join('');let connected=state.clues.includes('photo')&&state.clues.includes('timetable');let truth=state.clues.includes('letter')&&state.clues.includes('mechanism');panel(`<div class="panel-kicker">PIN THE FRAGMENTS TOGETHER</div><h2>The clue board</h2><p class="lead">Choose two details to see what they might share. The town will not solve it for you.</p>${have.length<2?`<p>You need at least two pieces before a pattern can emerge. You have ${have.length}.</p>`:`<div class="clue-board">${nodes}<div class="board-link">↔</div><div style="grid-column:1/-1;text-align:center;color:#8c8d7b;font-size:10px">${state.boardPick?'Now choose another clue to compare':'Select a clue, then another'}</div></div><div class="btn-row"><button class="action gold" data-act="connect">Connect these clues</button></div>`}${connected?`<div class="entry"><strong>✦ A plan, not a coincidence</strong><p>The photograph and timetable both point to the 8:17. June and Elias intended to leave together.</p></div>`:''}${truth?`<div class="entry"><strong>✦ Silence kept in a small case</strong><p>The watch was deliberately stopped. Its hidden letter explains why Elias stayed — and why he never returned.</p></div>`:''}<div class="divider"></div><button class="action secondary" data-act="journal">Back to journal</button>`,true);}
function inspect(id){if(id==='watch'){if(!state.clues.includes('watch'))addClue('watch');panel(`<div class="panel-kicker">OBJECT STUDY · 01</div><h2>The pocket watch</h2><p class="lead">Old brass, darkened at the edges. Its quiet has a weight to it.</p><div style="margin:20px auto;width:150px;height:150px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#d1b46c 0,#8d7045 62%,#443d2b 67%,#211f1a 72%);box-shadow:0 12px 25px #55452b66"><div style="width:108px;height:108px;border-radius:50%;background:#dfcf9e;border:2px solid #6f5939;display:grid;place-items:center;font:26px 'Playfair Display';color:#4b4838;position:relative">8:17<span style="position:absolute;bottom:15px;font:8px 'DM Sans';letter-spacing:1px">FOR JUNE · E.</span></div></div><p>The hands stopped at <b>8:17</b>. On the back: <i>“For June. 8:17. E.”</i></p><p>Press <b>E</b> again when you have Theo’s help to examine the seam more closely.</p><div class="btn-row"><button class="action secondary" data-act="journal">Read journal</button></div>`);return;}
if(id==='photo'){addClue('photo');panel(`<div class="panel-kicker">FOUND OBJECT · SHOP WINDOW</div><h2>The photograph</h2><p class="lead">Two young people stand at the station, squinting into the sun.</p><p>The young man wears the same watch chain. On the back, in a slanted hand: <i>“June says the 8:17 is lucky. —E.”</i></p><p>A memory, neatly pressed between the pages of a book.</p><button class="action secondary" data-act="journal">Keep it in your journal</button>`);return;}
if(id==='timetable'){addClue('timetable');panel(`<div class="panel-kicker">FOUND OBJECT · STATION WAITING ROOM</div><h2>One last train</h2><p class="lead">The timetable is soft at the folds and freckled with rain marks.</p><p>The 8:17 ran toward the coast. In the margin: <i>“Platform 2. Don’t be late this time.”</i> Someone underlined the date twice.</p><button class="action secondary" data-act="journal">Keep it in your journal</button>`);return;}
if(id==='mechanism'){if(!state.clues.includes('mechanism'))addClue('mechanism');panel(`<div class="panel-kicker">THE CLOCK & CROW · OBJECT STUDY</div><h2>A careful repair</h2><p class="lead">Theo turns the watch in the light, then lets out a delighted little breath.</p><p>“Aha. It isn’t broken, you see. Someone stopped it by hand. And this little lip here — someone has opened the inner case before. There’s paper tucked behind the works, I’d wager.”</p><p>There is only one person who could have hidden it.</p><button class="action gold" data-act="letter">Examine the hidden seam</button>`);return;}
if(id==='letter'){if(!state.clues.includes('letter'))addClue('letter');panel(`<div class="panel-kicker">THE LAST, QUIET PIECE</div><h2>Elias’s letter</h2><p class="lead">Folded small enough to hide behind the watch face, the paper has yellowed at its edges.</p><p class="ending">“June — Father took ill that afternoon. I could not leave him alone, not even for the length of one journey. I thought I would write tomorrow, when I had the words. Tomorrow became years. I kept your watch, and the place beside me on the train. I am sorry I let silence tell the story for me. —Elias.”</p><p>The watch was not lost. It was carried, every year, with an apology he never managed to send.</p><button class="action gold" data-act="june-final">Take the letter to June</button><button class="action secondary" data-act="journal">Sit with this a moment</button>`);return;}
if(id==='shelf'){panel(`<div class="panel-kicker">A GOOD PLACE FOR FOUND THINGS</div><h2>The window shelf</h2><p class="lead">A framed photograph sits here in the late afternoon light.</p><p>The faces in it seem less like a mystery now, more like two young people making a plan.</p><div class="btn-row"><button class="action secondary" data-act="photo">Look at the photograph</button><button class="action secondary" data-act="decor">Change the shelf</button></div>`);return;}
if(id==='decor'){const next=state.decor==='fern'?'lamp':state.decor==='lamp'?'flowers':'fern';state.decor=next;save();toast(`The shelf feels different with ${next==='fern'?'a fern':next==='lamp'?'a little lamp':'flowers'} there.`);closeModal();return;}
if(id==='door'){const options=Object.keys(places).filter(p=>p!==state.location);panel(`<div class="panel-kicker">A SHORT WALK IN THE RAIN</div><h2>Where to?</h2><p class="lead">The town is small enough to know by heart, if you take your time.</p>${options.map(id=>`<button class="choice" data-loc="${id}"><strong>${places[id].name.split(' · ').pop()}</strong><span>${id==='street'?'The lane, old brick, and the neighbor next door.':id==='station'?'A quiet platform and the old waiting room.':id==='repair'?'Theo’s clock shop, warm as a pocket.'}</span></button>`).join('')}`);return;}
}
function talk(name){state.topics[name]=true;const c=characters[name];state.dialogueCount[name]=(state.dialogueCount[name]||0)+1;let line='';if(name==='Mara')line=state.ending?'I’ve been thinking about what you did. It feels like Grandfather is a little less distant now.':state.clues.includes('letter')?'I’m glad he wrote it, even if it took all those years to find its way out. What do you think June would want?':state.clues.includes('watch')?'He kept it all those years. I never knew he had a life here before us.':'I found it in his desk. He was always so careful with things — even the things he never talked about.';
if(name==='June')line=state.ending==='returned'?'It sits on the mantel now. I don’t wind it. Some things can rest. Thank you for bringing the truth, not a tidy answer.':state.ending==='kept'?'I understand. The past belongs to whoever can carry it gently. I’m glad it has a safe place.':'The 8:17. I remember the platform and the rain on my sleeves. Elias was meant to be there. I waited until the station lamps came on.';
if(name==='Theo')line=state.clues.includes('mechanism')?'I found the seam you noticed. It’s been opened with a watchmaker’s tool — a careful hand, not an accident.':'Ah, a pocket watch. They’re tiny rooms, really. Gears, a spring, and sometimes somebody’s whole heart.';
if(name==='Rowan')line=state.ending==='returned'?'June came by this morning. She didn’t say much. She asked if I had any tea with orange peel. I made a pot.':'I’ve watched people keep things in boxes for years. Sometimes a little light helps them decide what the thing is for.';
state.memories.push(`${name}: ${line.slice(0,100)}${line.length>100?'…':''}`);save();const topics=name==='June'?['Ask about Elias','Ask about the 8:17','Ask what she remembers']:name==='Theo'?['Ask about the watch','Ask about the hidden seam']:name==='Mara'?['Ask about her grandfather','Ask what she hopes to learn']:['Ask about the neighborhood','Ask what Rowan has noticed'];panel(`<div class="panel-kicker">A CONVERSATION IN BRACKENFORD</div><div class="npc"><div class="portrait">${c.mark}</div><div><strong>${name}</strong><small>${c.look}</small></div></div><p class="dialogue">“${line}”</p><div class="memories">${c.tone}</div><div class="divider"></div><div class="btn-row">${topics.map((t,i)=>`<button class="action secondary" data-topic="${name}" data-answer="${i}">${t}</button>`).join('')}</div>${name==='June'&&state.clues.includes('letter')&&!state.ending?'<div class="btn-row"><button class="action gold" data-act="ending">Show June the letter & watch</button></div>':''}<div class="btn-row"><button class="action secondary" data-act="close">Say goodbye</button></div>`);}
function topic(name,index){let answers={Mara:['He was gentle, but private. After Gran died he spent more time in the garden. I think there were rooms in him I never saw.','I don’t know. I’d like the truth to be kind, but it doesn’t have to be.'],June:['He made little wooden birds for the station children. He could make a thing feel as if it had always belonged to you.','The 8:17 was the last train toward the coast. We’d both saved for the fare. I carried one small case.'],Theo:['It’s a lovely old movement. Kept in good condition, which means it mattered.','See this lip? It’s been opened before. There’s a fine slip of paper just behind the inner plate.'],Rowan:['This street’s good at holding on. Even the rain seems to remember who walked here.','June used to take the long way home past the station. Some routes become habits before we know why.']};let line=(answers[name]||[])[index]||'There are things I know, and things I only suspect. I try not to mix them up.';state.memories.push(`${name}: ${line.slice(0,100)}`);save();panel(`<div class="panel-kicker">A CONVERSATION IN BRACKENFORD</div><div class="npc"><div class="portrait">${characters[name].mark}</div><div><strong>${name}</strong><small>${characters[name].look}</small></div></div><p class="dialogue">“${line}”</p><div class="btn-row"><button class="action secondary" data-act="talk-${name}">Continue talking</button><button class="action secondary" data-act="close">Say goodbye</button></div>`);}

function doEnding(){if(!state.clues.includes('letter'))return;panel(`<div class="panel-kicker">A CHOICE, NOT A TEST</div><h2>What should be done?</h2><p class="lead">The watch and letter have waited a long time. June is still here to decide what they mean.</p><button class="choice" data-end="returned"><strong>Return them to June</strong><span>Let her read Elias’s words. The watch can rest on her mantel, and the truth can be hers to keep.</span></button><button class="choice" data-end="kept"><strong>Keep them safe in the shop</strong><span>June once chose to stay. Leave the objects here, where the story can be remembered without asking her to carry it again.</span></button>`);}
function finishEnding(choice){state.ending=choice;state.clues.push('choice');state.progress=5;save();panel(`<div class="panel-kicker">THE WATCH THAT WAITED · A SMALL ENDING</div><h2>${choice==='returned'?'A place on the mantel':'A place among the found things'}</h2><p class="ending">${choice==='returned'?'June reads the letter twice. The second time, she takes off her glasses and holds the paper against her palm. “I did wonder,” she says. “Not every day. But I did.” She asks you to leave the watch with her. A week later, Rowan tells you there is a small brass circle on June’s mantel, beside a pot of late flowers.':'You keep the letter with the watch, on the little shelf by the window. June comes in once, reads the first few lines, and puts the page back. “I’m glad he wrote it,” she says. “I’m glad it found a home.” Some afternoons she sits by the window, where the light catches the brass.'}</p><p class="lead">The years remain what they were. But the silence is no longer the only story.</p><div class="btn-row"><button class="action gold" data-act="close">Return to the shop</button><button class="action secondary" data-act="journal">Read your notes</button></div>`);toast('Mystery complete · The shop remembers');}
function nearest(){const loc=state.location,p=state.player;let arr=[];const add=(x,y,r,id,label,kind='inspect')=>{let d=Math.hypot(p.x-x,p.y-y);if(d<r)arr.push({d,id,label,kind})};
if(loc==='shop'){add(500,350,90,'watch','The pocket watch');add(285,300,75,'shelf','Window shelf');add(790,480,100,'door','The front door','door');add(310,460,85,'Mara','Mara','talk');add(650,270,80,'decor','The shelf decor');}
if(loc==='street'){add(195,405,85,'Rowan','Rowan','talk');add(790,450,100,'door','The street crossing','door');add(470,250,95,'door','The station path','door');add(280,230,65,'shopdoor','Your shop','door');}
if(loc==='station'){add(500,360,100,'timetable','Old timetable');add(280,440,90,'June','June','talk');add(790,475,100,'door','Back to Lantern Lane','door');add(500,230,60,'photo','A forgotten photograph');}
if(loc==='repair'){add(515,360,100,'mechanism','Theo’s workbench');add(320,450,90,'Theo','Theo','talk');add(790,470,100,'door','Back to Lantern Lane','door');add(620,245,65,'watch','The pocket watch');}
arr.sort((a,b)=>a.d-b.d);return arr[0]||null;}
let pulse=0,ambient=[],rain=[],last=0;
function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(innerWidth*dpr);canvas.height=Math.floor(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
function draw(){const w=innerWidth,h=innerHeight;ctx.clearRect(0,0,w,h);let scale=Math.min(w/W,h/H),ox=(w-W*scale)/2,oy=(h-H*scale)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);drawScene();ctx.restore();requestAnimationFrame(draw);}
function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function drawScene(){let loc=state.location;const outdoor=loc!=='shop'&&loc!=='repair';let bg=loc==='shop'?'#66503d':loc==='repair'?'#64513f':loc==='station'?'#536763':'#536761';ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
if(loc==='shop')drawShop();if(loc==='street')drawStreet();if(loc==='station')drawStation();if(loc==='repair')drawRepair();
if(outdoor)drawRain();drawPlayer();
const n=nearest();state.near=n;const btn=document.getElementById('interactBtn');if(n){btn.style.opacity='1';btn.innerHTML=`<span>✦</span> ${n.kind==='talk'?'Speak with':n.kind==='door'?'Walk to':'Look closer'} ${n.label}<kbd>E</kbd>`;}else{btn.style.opacity='.6';btn.innerHTML='<span>✦</span> Look closer <kbd>E</kbd>';}
if(pulse>0){pulse*=.94;ctx.beginPath();ctx.arc(state.player.x,state.player.y-27,24+(1-pulse)*32,0,Math.PI*2);ctx.strokeStyle=`rgba(235,202,137,${pulse*.55})`;ctx.lineWidth=2;ctx.stroke();}
}
function drawShop(){// painted wood and warm lamplight
ctx.fillStyle='#594532';ctx.fillRect(0,0,W,H);ctx.fillStyle='#8c7258';ctx.fillRect(35,90,930,515);for(let y=106;y<600;y+=42){ctx.strokeStyle='#a88c69';ctx.globalAlpha=.22;ctx.beginPath();ctx.moveTo(38,y);ctx.lineTo(962,y);ctx.stroke();}ctx.globalAlpha=1;
ctx.fillStyle='#c09962';ctx.fillRect(60,102,880,9);ctx.fillStyle='#2e3b35';ctx.fillRect(84,125,240,157);ctx.fillStyle='#b9a072';ctx.fillRect(94,135,220,137);ctx.fillStyle='#758b7c';ctx.fillRect(100,141,98,125);ctx.fillStyle='#7a8c7d';ctx.fillRect(208,141,100,125);ctx.strokeStyle='#725b3c';ctx.lineWidth=8;ctx.strokeRect(84,125,240,157);ctx.beginPath();ctx.moveTo(203,137);ctx.lineTo(203,273);ctx.stroke();ctx.beginPath();ctx.moveTo(90,208);ctx.lineTo(318,208);ctx.stroke();
// shelves & found objects
rounded(350,128,245,18,3,'#493b2d');rounded(675,130,220,18,3,'#493b2d');drawObject(390,108,'#bd8b62','vase');drawObject(475,105,'#d9bd7a','book');drawObject(540,110,'#79867a','jar');drawObject(718,112,'#bd8b62','clock');drawObject(790,105,'#d2bf91','books');
// counter
rounded(359,303,272,125,5,'#4e3c2c','#c09b67');rounded(373,313,244,20,3,'#b69560');ctx.fillStyle='#6b4c37';ctx.fillRect(376,333,238,85);ctx.fillStyle='#bf9860';ctx.fillRect(388,344,18,74);ctx.fillRect(584,344,18,74);rounded(425,330,120,56,4,'#46382b','#c4a06a');drawWatch(484,354,24);
// rug + lamp glow
