function drawObject(x,y,color,type){ctx.save();ctx.translate(x,y);if(type==='vase'){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-8,-9);ctx.lineTo(8,-9);ctx.lineTo(12,10);ctx.quadraticCurveTo(0,20,-12,10);ctx.fill();ctx.fillRect(-6,-14,12,6);}else if(type==='book'||type==='books'){ctx.fillStyle=color;ctx.fillRect(-15,-12,30,25);ctx.fillStyle='#634c34';ctx.fillRect(-12,-9,3,20);ctx.strokeStyle='#f0d9a8';ctx.beginPath();ctx.moveTo(-7,-3);ctx.lineTo(10,-3);ctx.moveTo(-7,2);ctx.lineTo(8,2);ctx.stroke();}else if(type==='clock'){ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,15,0,7);ctx.fill();ctx.fillStyle='#e2d3a6';ctx.beginPath();ctx.arc(0,0,11,0,7);ctx.fill();ctx.strokeStyle='#534630';ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-7);ctx.moveTo(0,0);ctx.lineTo(6,2);ctx.stroke();}else{ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-10,-13,20,25,5);ctx.fill();ctx.fillStyle='#e6d19f';ctx.fillRect(-3,-19,7,6);}ctx.restore();}
function drawWatch(x,y,r){ctx.save();ctx.fillStyle='#443d2b';ctx.beginPath();ctx.arc(x,y,r+3,0,7);ctx.fill();ctx.fillStyle='#c9a65f';ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.fillStyle='#e8d9aa';ctx.beginPath();ctx.arc(x,y,r*.76,0,7);ctx.fill();ctx.strokeStyle='#62533a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y-r*.48);ctx.moveTo(x,y);ctx.lineTo(x+r*.36,y+r*.2);ctx.stroke();ctx.fillStyle='#4b4333';ctx.beginPath();ctx.arc(x,y,2,0,7);ctx.fill();ctx.restore();}
function drawNPC(x,y,mark,coat){ctx.save();ctx.globalAlpha=.25;ctx.fillStyle='#1d2621';ctx.beginPath();ctx.ellipse(x,y+5,18,8,0,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=coat;ctx.beginPath();ctx.moveTo(x-15,y-20);ctx.lineTo(x-10,y-7);ctx.lineTo(x-14,y+3);ctx.lineTo(x+14,y+3);ctx.lineTo(x+9,y-7);ctx.lineTo(x+14,y-20);ctx.closePath();ctx.fill();ctx.fillStyle='#d3b99a';ctx.beginPath();ctx.arc(x,y-27,10,0,7);ctx.fill();ctx.fillStyle=mark==='M'?'#3e2e29':mark==='J'?'#d7d2c4':mark==='T'?'#584b3d':'#4a4336';ctx.beginPath();ctx.arc(x,y-31,10,Math.PI,0);ctx.fill();ctx.fillStyle='#493e32';ctx.font='9px "DM Sans"';ctx.textAlign='center';ctx.fillText(mark,x,y+1);ctx.restore();}
function drawPlayer(){let x=state.player.x,y=state.player.y,walking=state.keys.ArrowUp||state.keys.ArrowDown||state.keys.ArrowLeft||state.keys.ArrowRight||state.keys.w||state.keys.a||state.keys.s||state.keys.d;ctx.save();ctx.globalAlpha=.24;ctx.fillStyle='#18221e';ctx.beginPath();ctx.ellipse(x,y+4,17,7,0,0,7);ctx.fill();ctx.globalAlpha=1;let bob=walking?Math.sin(Date.now()/80)*2:0;ctx.fillStyle='#65796b';ctx.beginPath();ctx.moveTo(x-13,y-22+bob);ctx.lineTo(x-9,y-7+bob);ctx.lineTo(x-12,y+3);ctx.lineTo(x+12,y+3);ctx.lineTo(x+9,y-7+bob);ctx.lineTo(x+13,y-22+bob);ctx.closePath();ctx.fill();ctx.fillStyle='#d8bea0';ctx.beginPath();ctx.arc(x,y-28+bob,9,0,7);ctx.fill();ctx.fillStyle='#46362d';ctx.beginPath();ctx.arc(x,y-31+bob,9,Math.PI,0);ctx.fill();ctx.restore();}
function drawSign(x,y,text){ctx.fillStyle='#e9d8b8';ctx.globalAlpha=.85;ctx.font='10px "DM Sans"';ctx.textAlign='center';ctx.fillText(text,x,y);ctx.globalAlpha=1;}
function drawRain(){let w=1000,h=650;if(rain.length<90)for(let i=rain.length;i<90;i++)rain.push({x:Math.random()*w,y:Math.random()*h,s:2+Math.random()*4});ctx.strokeStyle='rgba(193,213,205,.27)';ctx.lineWidth=1;rain.forEach(r=>{r.x-=.8;r.y+=r.s;if(r.y>h){r.y=-10;r.x=Math.random()*w}if(r.x<0)r.x=w;ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+13);ctx.stroke()});}
function move(dt){if(modal.innerHTML)return;let dx=0,dy=0,k=state.keys;if(k.ArrowUp||k.w)dy--;if(k.ArrowDown||k.s)dy++;if(k.ArrowLeft||k.a)dx--;if(k.ArrowRight||k.d)dx++;if(dx||dy){let len=Math.hypot(dx,dy);let speed=130*(dt/1000);state.player.x=Math.max(50,Math.min(950,state.player.x+dx/len*speed));state.player.y=Math.max(120,Math.min(570,state.player.y+dy/len*speed));}}
let then=performance.now();function loop(t){let dt=Math.min(40,t-then);then=t;move(dt);requestAnimationFrame(loop);}requestAnimationFrame(loop);requestAnimationFrame(draw);
function interact(){if(modal.innerHTML){return}let n=nearest();if(!n){toast('Nothing close by. Take a little wander.');return}if(n.kind==='talk'){talk(n.id);return}if(n.kind==='door'){if(state.location==='shop')inspect('door');else if(state.location==='street'){if(n.label.includes('shop'))setLoc('shop');else if(n.label.includes('station'))setLoc('station');else inspect('door')}else if(state.location==='station')setLoc('street');else setLoc('street');return}if(n.id==='shopdoor'){setLoc('shop');return}if(n.id==='watch'&&state.location==='repair'&&state.clues.includes('mechanism'))inspect('letter');else inspect(n.id);}
window.addEventListener('keydown',e=>{let k=e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();state.keys[k]=true;if(k==='e'||k==='E')interact();if(k==='j'||k==='J')journal();if(k==='b'||k==='B')board();if(k==='Escape'){if(modal.innerHTML)closeModal();else showMenu();}});window.addEventListener('keyup',e=>state.keys[e.key]=false);window.addEventListener('resize',resize);resize();
document.getElementById('interactBtn').onclick=interact;document.getElementById('journalBtn').onclick=()=>journal();document.getElementById('boardBtn').onclick=board;document.getElementById('inventoryBtn').onclick=inventory;document.getElementById('pauseBtn').onclick=showMenu;document.getElementById('brandHome').onclick=showMenu;
document.getElementById('soundBtn').onclick=e=>{state.sound=!state.sound;e.currentTarget.querySelector('span').textContent=state.sound?'Sound on':'Sound off';toast(state.sound?'The rain sounds a little closer.':'Sound off');};
document.querySelectorAll('.touch-pad button').forEach(b=>{let d=b.dataset.dir,key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[d];b.addEventListener('pointerdown',e=>{e.preventDefault();state.keys[key]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>state.keys[key]=false));});
modal.addEventListener('click',e=>{let el=e.target.closest('button');if(!el)return;if(el.classList.contains('close')){closeModal();return}if(el.dataset.act){let a=el.dataset.act;if(a==='resume'){closeModal();return}if(a==='new'){startNew();return}if(a==='board'){board();return}if(a==='journal'){journal();return}if(a==='inventory'){inventory();return}if(a==='close'){closeModal();return}if(a==='letter'){inspect('letter');return}if(a==='ending'){doEnding();return}if(a==='june-final'){doEnding();return}if(a==='decor'){inspect('decor');return}if(a==='settings'){panel(`<div class="panel-kicker">A QUIET WAY TO PLAY</div><h2>Settings & controls</h2><p class="lead">Find your own pace around Brackenford.</p><div class="entry"><strong>Move</strong><p>WASD or arrow keys · touch arrows on phones</p></div><div class="entry"><strong>Interact</strong><p>E or the “Look closer” button</p></div><div class="entry"><strong>Journal / clue board</strong><p>J / B, or use the buttons at the top</p></div><div class="entry"><strong>Sound</strong><p>Use the music note button to toggle ambience.</p></div><button class="action secondary" data-act="close">Back</button>`);return}if(a.startsWith('talk-')){talk(a.slice(5));return}}
if(el.dataset.loc){let target=el.dataset.loc;if(state.location==='shop'&&target!=='street'){toast('Step outside to reach that place.');return}if(state.location==='street'&&target==='shop'){setLoc('shop');return}if(state.location==='street'&&target==='station'){setLoc('station');return}if(state.location==='street'&&target==='repair'){setLoc('repair');return}setLoc(target);return}
if(el.dataset.tab){journal(el.dataset.tab);return}if(el.dataset.pick){if(!state.boardPick)state.boardPick=el.dataset.pick;else if(state.boardPick===el.dataset.pick)state.boardPick=null;else state.boardSecond=el.dataset.pick;board();return}if(el.dataset.act==='connect'){let ids=[state.boardPick,state.boardSecond];if(ids.includes('photo')&&ids.includes('timetable')){toast('Connection found · A plan, not a coincidence');state.memories.push('The photograph and timetable connect June and Elias to the 8:17.');}else if(ids.includes('mechanism')&&ids.includes('letter')){toast('Connection found · Silence kept in a small case');}else toast('A connection is possible. Keep looking at the details.');state.boardPick=null;state.boardSecond=null;save();board();return}
if(el.dataset.topic){topic(el.dataset.topic,Number(el.dataset.answer));return}if(el.dataset.end){finishEnding(el.dataset.end);return}
});
// ensure start menu and resume
if(load()){document.getElementById('clueCount').textContent=state.clues.length;document.getElementById('locationName').textContent=places[state.location]?.name||places.shop.name;showMenu();}else showMenu();
})();

