10	function interact(){if(modal.innerHTML){return}let n=nearest();if(!n){toast('Nothing close by. Take a little wander.');return}if(n.kind==='talk'){talk(n.id);return}if(n.kind==='door'){if(state.location==='shop')inspect('door');else if(state.location==='street'){if(n.label.includes('shop'))setLoc('shop');else if(n.label.includes('station'))setLoc('station');else inspect('door')}else if(state.location==='station')setLoc('street');else setLoc('street');return}if(n.id==='shopdoor'){setLoc('shop');return}if(n.id==='watch'&&state.location==='repair'&&state.clues.includes('mechanism'))inspect('letter');else inspect(n.id);}
11	window.addEventListener('keydown',e=>{let k=e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();state.keys[k]=true;if(k==='e'||k==='E')interact();if(k==='j'||k==='J')journal();if(k==='b'||k==='B')board();if(k==='Escape'){if(modal.innerHTML)closeModal();else showMenu();}});window.addEventListener('keyup',e=>state.keys[e.key]=false);window.addEventListener('resize',resize);resize();
12	document.getElementById('interactBtn').onclick=interact;document.getElementById('journalBtn').onclick=()=>journal();document.getElementById('boardBtn').onclick=board;document.getElementById('inventoryBtn').onclick=inventory;document.getElementById('pauseBtn').onclick=showMenu;document.getElementById('brandHome').onclick=showMenu;
13	document.getElementById('soundBtn').onclick=e=>{state.sound=!state.sound;e.currentTarget.querySelector('span').textContent=state.sound?'Sound on':'Sound off';toast(state.sound?'The rain sounds a little closer.':'Sound off');};
14	document.querySelectorAll('.touch-pad button').forEach(b=>{let d=b.dataset.dir,key={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'}[d];b.addEventListener('pointerdown',e=>{e.preventDefault();state.keys[key]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>state.keys[key]=false));});
15	modal.addEventListener('click',e=>{let el=e.target.closest('button');if(!el)return;if(el.classList.contains('close')){closeModal();return}if(el.dataset.act){let a=el.dataset.act;if(a==='resume'){closeModal();return}if(a==='new'){startNew();return}if(a==='board'){board();return}if(a==='journal'){journal();return}if(a==='inventory'){inventory();return}if(a==='close'){closeModal();return}if(a==='letter'){inspect('letter');return}if(a==='ending'){doEnding();return}if(a==='june-final'){doEnding();return}if(a==='decor'){inspect('decor');return}if(a==='settings'){panel(`<div class="panel-kicker">A QUIET WAY TO PLAY</div><h2>Settings & controls</h2><p class="lead">Find your own pace around Brackenford.</p><div class="entry"><strong>Move</strong><p>WASD or arrow keys · touch arrows on phones</p></div><div class="entry"><strong>Interact</strong><p>E or the “Look closer” button</p></div><div class="entry"><strong>Journal / clue board</strong><p>J / B, or use the buttons at the top</p></div><div class="entry"><strong>Sound</strong><p>Use the music note button to toggle ambience.</p></div><button class="action secondary" data-act="close">Back</button>`);return}if(a.startsWith('talk-')){talk(a.slice(5));return}}
16	if(el.dataset.loc){let target=el.dataset.loc;if(state.location==='shop'&&target!=='street'){toast('Step outside to reach that place.');return}if(state.location==='street'&&target==='shop'){setLoc('shop');return}if(state.location==='street'&&target==='station'){setLoc('station');return}if(state.location==='street'&&target==='repair'){setLoc('repair');return}setLoc(target);return}
17	if(el.dataset.tab){journal(el.dataset.tab);return}if(el.dataset.pick){if(!state.boardPick)state.boardPick=el.dataset.pick;else if(state.boardPick===el.dataset.pick)state.boardPick=null;else state.boardSecond=el.dataset.pick;board();return}if(el.dataset.act==='connect'){let ids=[state.boardPick,state.boardSecond];if(ids.includes('photo')&&ids.includes('timetable')){toast('Connection found · A plan, not a coincidence');state.memories.push('The photograph and timetable connect June and Elias to the 8:17.');}else if(ids.includes('mechanism')&&ids.includes('letter')){toast('Connection found · Silence kept in a small case');}else toast('A connection is possible. Keep looking at the details.');state.boardPick=null;state.boardSecond=null;save();board();return}
18	if(el.dataset.topic){topic(el.dataset.topic,Number(el.dataset.answer));return}if(el.dataset.end){finishEnding(el.dataset.end);return}
19	});
20	// ensure start menu and resume
21	if(load()){document.getElementById('clueCount').textContent=state.clues.length;document.getElementById('locationName').textContent=places[state.location]?.name||places.shop.name;showMenu();}else showMenu();
22	})();

