(()=>{'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),modal=document.querySelector('#modalLayer'),saveKey='littleThings.v1';
const S={started:false,loc:'shop',x:500,y:455,clues:[],visited:['shop'],talked:{},ending:'',decor:'fern',sound:true};
const P={shop:'THE LITTLE THINGS · SHOP',street:'LANTERN LANE · TOWN STREET',station:'BRACKENFORD · OLD STATION',repair:'THE CLOCK & CROW · REPAIR SHOP'};
const C={watch:['◷','The stopped watch','8:17 · For June. E.','An old brass pocket watch, warm from being carried. The hands stopped at 8:17. On its back: “For June. 8:17. E.”'],photo:['▧','The photograph','Two young friends at the station','A sun-faded photograph. On its back: “June says the 8:17 is lucky. —E.” The young man wears this same watch chain.'],timetable:['▤','The 8:17 timetable','The last train out, on a wet Tuesday','The 8:17 was the last train toward the coast. A pencilled note: “Platform 2. Don’t be late this time.”'],mechanism:['⚙','A careful repair','The case has been opened before','Theo finds a seam behind the inner case. The watch was stopped by hand, not broken. Something thin is hidden inside.'],letter:['✉','Elias’s unsent letter','A letter folded behind the watch face','“June — Father took ill that afternoon. I could not leave him alone, not even for one journey. I thought I would write tomorrow, when I had the words. Tomorrow became years. I kept your watch, and the place beside me on the train. I am sorry I let silence tell the story for me. —Elias.”']};
const people={Mara:['M','rust-red coat, rain-bright curls','Warm, thoughtful; often finds the right question a moment late.'],June:['J','silver hair and station-blue scarf','Measured and exact; when moved, her sentences get shorter.'],Theo:['T','brass spectacles, tool-filled waistcoat','Delighted by mechanism; speaks to clocks as if they are shy animals.'],Rowan:['R','moss-green shawl, book basket','Dryly kind, observant, never in a hurry to finish a thought.']};
function save(){try{localStorage.setItem(saveKey,JSON.stringify(S))}catch{}}function load(){try{let d=JSON.parse(localStorage.getItem(saveKey));if(d){Object.assign(S,d);return true}}catch{}return false}
function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2100)}
function close(){modal.innerHTML=''}function panel(html,wide=false){modal.innerHTML=`<div class="panel ${wide?'wide':''}"><button class="close">×</button>${html}</div>`}
function menu(){modal.innerHTML=`<div class="menu-card"><div class="menu-title">THE LITTLE<br>THINGS</div><div class="menu-subtitle">A STORY IN FOUR PLACES</div><p>A rain-soft mystery about a watch, a train that left, and the things we almost said.</p>${S.started?'<button class="action" data-a="resume">Continue your story</button>':''}<button class="action" data-a="new">${S.started?'Begin again':'Open the shop'}</button><button class="action secondary" data-a="settings">Settings & controls</button><div style="font-size:9px;color:#c5b895;margin-top:18px">WASD / arrows · E interact · J journal · B clue board</div></div>`}
function newGame(){Object.assign(S,{started:true,loc:'shop',x:500,y:455,clues:[],visited:['shop'],talked:{},ending:'',decor:'fern'});save();close();toast('A small beginning.')}
function clue(id){if(S.clues.includes(id))return;S.clues.push(id);save();document.querySelector('#clueCount').textContent=S.clues.length;toast('A detail worth keeping · Journal updated')}
function journal(tab='Evidence'){let tabs=['Evidence','People','Places','Notes'],body='';if(tab==='Evidence')body=S.clues.length?S.clues.map(id=>`<div class="entry"><strong>${C[id][0]} &nbsp;${C[id][1]}</strong><small>KEPT</small><p>${C[id][2]}</p></div>`).join(''):'<p>Your pockets are empty. Walk near something interesting and press <b>E</b>.</p>';if(tab==='People')body=Object.entries(people).map(([n,p])=>`<div class="entry"><strong>${n}</strong><small>${S.talked[n]?'MET':'NOT MET'}</small><p>${S.talked[n]?p[2]:'Someone you may come across in Brackenford.'}</p></div>`).join('');if(tab==='Places')body=Object.entries(P).map(([id,n])=>`<div class="entry"><strong>${n}</strong><small>${S.visited.includes(id)?'VISITED':'UNSEEN'}</small><p>${id==='shop'?'A snug room of found things and lamplight.':id==='street'?'The narrow lane between the shop and station.':id==='station'?'An old platform where the 8:17 once waited.':'A repair shop warm as a pocket.'}</p></div>`).join('');if(tab==='Notes')body=`<div class="entry"><strong>The Watch That Waited</strong><small>${S.ending?'RESOLVED':'IN PROGRESS'}</small><p>${S.ending?'Some stories do not undo the years. They make room for a kinder telling.':`You have ${S.clues.length} of 5 pieces. A stopped watch, an old friendship, and a missed train.`}</p></div>`;panel(`<div class="panel-kicker">A POCKET-SIZED RECORD</div><h2>The Journal</h2><p class="lead">Little details have a way of finding one another.</p><div class="tabs">${tabs.map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${body}<div class="btn-row"><button class="action secondary" data-a="board">Open clue board</button><button class="action secondary" data-a="inventory">Pocket inventory</button></div>`,true)}

