 function journal(tab='Evidence'){let tabs=['Evidence','People','Places','Notes'],body='';if(tab==='Evidence')body=S.clues.length?S.clues.map(id=>`<div class="entry"><strong>${C[id][0]} &nbsp;${C[id][1]}</strong><small>KEPT</small><p>${C[id][2]}</p></div>`).join(''):'<p>Your pockets are empty. Walk near something interesting and press <b>E</b>.</p>';if(tab==='People')body=Object.entries(people).map(([n,p])=>`<div class="entry"><strong>${n}</strong><small>${S.talked[n]?'MET':'NOT MET'}</small><p>${S.talked[n]?p[2]:'Someone you may come across in Brackenford.'}</p></div>`).join('');if(tab==='Places')body=Object.entries(P).map(([id,n])=>`<div class="entry"><strong>${n}</strong><small>${S.visited.includes(id)?'VISITED':'UNSEEN'}</small><p>${id==='shop'?'A snug room of found things and lamplight.':id==='street'?'The narrow lane between the shop and station.':id==='station'?'An old platform where the 8:17 once waited.':'A repair shop warm as a pocket.'}</p></div>`).join('');if(tab==='Notes')body=`<div class="entry"><strong>The Watch That Waited</strong><small>${S.ending?'RESOLVED':'IN PROGRESS'}</small><p>${S.ending?'Some stories do not undo the years. They make room for a kinder telling.':`You have ${S.clues.length} of 5 pieces. A stopped watch, an old friendship, and a missed train.`}</p></div>`;panel(`<div class="panel-kicker">A POCKET-SIZED RECORD</div><h2>The Journal</h2><p class="lead">Little details have a way of finding one another.</p><div class="tabs">${tabs.map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${body}<div class="btn-row"><button class="action secondary" data-a="board">Open clue board</button><button class="action secondary" data-a="inventory">Pocket inventory</button></div>`,true)}
+function inventory(){let list=S.clues.map(id=>C[id]);panel(`<div class="panel-kicker">WHAT YOU’VE FOUND</div><h2>Your pockets</h2><p class="lead">A careful keeper makes room for small things.</p>${list.length?`<div class="grid">${list.map(c=>`<div class="card"><div class="glyph">${c[0]}</div><strong>${c[1]}</strong><small>${c[2]}</small></div>`).join('')}</div>`:'<p>Nothing yet. The watch is waiting on the counter.</p>'}<div class="divider"></div><button class="action secondary" data-a="journal">Back to journal</button>`)}
+function board(){let found=S.clues.filter(x=>['watch','photo','timetable','mechanism','letter'].includes(x));panel(`<div class="panel-kicker">PIN THE FRAGMENTS TOGETHER</div><h2>The clue board</h2><p class="lead">Choose two details to see what they might share. The town will not solve it for you.</p>${found.length<2?`<p>You need two pieces before a pattern can emerge. You have ${found.length}.</p>`:`<div class="clue-board">${found.map(id=>`<button class="clue-node ${S.pick===id?'selected':''}" data-pick="${id}"><strong>${C[id][0]} ${C[id][1]}</strong><small>${C[id][2]}</small></button>`).join('')}<div class="board-link">↔</div><div style="grid-column:1/-1;text-align:center;color:#8c8d7b;font-size:10px">${S.pick?'Choose another clue to compare':'Select a clue, then another'}</div></div><div class="btn-row"><button class="action gold" data-a="connect">Connect these clues</button></div>`}${S.clues.includes('photo')&&S.clues.includes('timetable')?'<div class="entry"><strong>✦ A plan, not a coincidence</strong><p>The photograph and timetable both point to the 8:17. June and Elias intended to leave together.</p></div>':''}${S.clues.includes('letter')?'<div class="entry"><strong>✦ Silence kept in a small case</strong><p>The watch was deliberately stopped. Its hidden letter explains why Elias stayed — and why he never returned.</p></div>':''}<div class="divider"></div><button class="action secondary" data-a="journal">Back to journal</button>`,true)}
+function location(loc){S.loc=loc;if(!S.visited.includes(loc))S.visited.push(loc);S.x=500;S.y=470;document.querySelector('#locationName').textContent=P[loc];save();close();toast(P[loc])}
+function inspect(id){if(id==='watch'){clue('watch');panel(`<div class="panel-kicker">OBJECT STUDY · 01</div><h2>The pocket watch</h2><p class="lead">Old brass, darkened at the edges. Its quiet has a weight to it.</p><div style="margin:20px auto;width:145px;height:145px;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#d1b46c 0,#8d7045 62%,#443d2b 67%,#211f1a 72%);box-shadow:0 12px 25px #55452b66"><div style="width:108px;height:108px;border-radius:50%;background:#dfcf9e;border:2px solid #6f5939;display:grid;place-items:center;font:23px 'Playfair Display';color:#4b4838">8:17<span style="position:absolute;transform:translateY(30px);font:8px 'DM Sans';letter-spacing:1px">FOR JUNE · E.</span></div></div><p>${C.watch[3]}</p><p>When Theo has a look, perhaps the case will tell you more.</p><button class="action secondary" data-a="journal">Read journal</button>`);return}if(id==='photo'){clue('photo');panel(`<div class="panel-kicker">FOUND OBJECT · WINDOW SHELF</div><h2>The photograph</h2><p class="lead">Two young people stand at the station, squinting into the sun.</p><p>${C.photo[3]}</p><button class="action secondary" data-a="journal">Keep it in your journal</button>`);return}if(id==='timetable'){clue('timetable');panel(`<div class="panel-kicker">FOUND OBJECT · STATION WAITING ROOM</div><h2>One last train</h2><p class="lead">The timetable is soft at the folds and freckled with rain marks.</p><p>${C.timetable[3]}</p><button class="action secondary" data-a="journal">Keep it in your journal</button>`);return}if(id==='mechanism'){if(!S.clues.includes('watch')){toast('Perhaps bring the watch to Theo first.');return}panel(`<div class="panel-kicker">THE CLOCK & CROW · OBJECT STUDY</div><h2>A careful repair</h2><p class="lead">Theo turns the watch in the light, then lets out a delighted little breath.</p><p>“Aha. It isn’t broken, you see. Someone stopped it by hand. And this little lip here — someone has opened the inner case before. There’s paper tucked behind the works, I’d wager.”</p><p>There is only one person who could have hidden it.</p><button class="action gold" data-a="letter">Examine the hidden seam</button>`);clue('mechanism');return}if(id==='letter'){clue('letter');panel(`<div class="panel-kicker">THE LAST, QUIET PIECE</div><h2>Elias’s letter</h2><p class="lead">Folded small enough to hide behind the watch face, the paper has yellowed at its edges.</p><p class="ending">${C.letter[3]}</p><p>The watch was not lost. It was carried, every year, with an apology he never managed to send.</p><button class="action gold" data-a="ending">Take the letter to June</button><button class="action secondary" data-a="journal">Sit with this a moment</button>`);return}if(id==='shelf'){panel(`<div class="panel-kicker">A GOOD PLACE FOR FOUND THINGS</div><h2>The window shelf</h2><p class="lead">A framed photograph sits here in the late afternoon light.</p><p>The faces seem less like a mystery now, more like two young people making a plan.</p><button class="action secondary" data-a="photo">Look at the photograph</button><button class="action secondary" data-a="decor">Change the shelf</button>`);return}if(id==='decor'){S.decor=S.decor==='fern'?'lamp':S.decor==='lamp'?'flowers':'fern';save();close();toast(`The shelf feels different with ${S.decor}.`);return}if(id==='door'){let destinations=S.loc==='shop'?['street']:S.loc==='street'?['shop','station','repair']:['street'];panel(`<div class="panel-kicker">A SHORT WALK IN THE RAIN</div><h2>Where to?</h2><p class="lead">The town is small enough to know by heart, if you take your time.</p>${destinations.map(d=>`<button class="choice" data-loc="${d}"><strong>${P[d].split(' · ').pop()}</strong><span>${d==='street'?'The lane, old brick, and Rowan next door.':d==='station'?'A quiet platform and the old waiting room.':'Theo’s clock shop, warm as a pocket.'}</span></button>`).join('')}`);return}}
+function talk(name){S.talked[name]=true;let line='';if(name==='Mara')line=S.clues.includes('watch')?'He kept it all those years. I never knew he had a life here before us.':'I found it in his desk. He was always so careful with things — even the things he never talked about.';if(name==='June')line=S.ending==='returned'?'It sits on the mantel now. I don’t wind it. Some things can rest. Thank you for bringing the truth, not a tidy answer.':S.ending==='kept'?'I understand. The past belongs to whoever can carry it gently. I’m glad it has a safe place.':'The 8:17. I remember the platform and the rain on my sleeves. Elias was meant to be there. I waited until the station lamps came on.';if(name==='Theo')line=S.clues.includes('mechanism')?'I found the seam you noticed. It’s been opened with a watchmaker’s tool — a careful hand, not an accident.':'Ah, a pocket watch. They’re tiny rooms, really. Gears, a spring, and sometimes somebody’s whole heart.';if(name==='Rowan')line='A town is mostly people leaving little pieces of themselves in one another’s rooms. Sometimes a little light helps them decide what the thing is for.';panel(`<div class="panel-kicker">A CONVERSATION IN BRACKENFORD</div><div class="npc"><div class="portrait">${people[name][0]}</div><div><strong>${name}</strong><small>${people[name][1]}</small></div></div><p class="dialogue">“${line}”</p><div class="memories">${people[name][2]}</div><div class="divider"></div>${name==='June'&&S.clues.includes('letter')&&!S.ending?'<button class="action gold" data-a="ending">Show June the letter & watch</button>':''}<div class="btn-row"><button class="action secondary" data-a="close">Say goodbye</button></div>`)}

