1: (()=>{'use strict';
2: const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d'),modal=document.querySelector('#modalLayer'),saveKey='littleThings.v1';
3: const S={started:false,loc:'shop',x:500,y:455,clues:[],visited:['shop'],talked:{},ending:'',decor:'fern',sound:true};
