13: function journal(tab='Evidence'){let tabs=['Evidence','People','Places','Notes'],body='';if(tab==='Evidence')body=S.clues.length?S.clues.map(id=>`<div class="entry"><strong>${C[id][0]} &nbsp;${C[id][1]}</strong><small>KEPT</small><p>${C[id][2]}</p></div>`).join(''):'<p>Your pockets are empty. Walk near something interesting and press <b>E</b>.</p>';if(tab==='People')body=Object.entries(people).map(([n,p])=>`<div class="entry"><strong>${n}</strong><small>${S.talked[n]?'MET':'NOT MET'}</small><p>${S.talked[n]?p[2]:'Someone you may come across in Brackenford.'}</p></div>`).join('');if(tab==='Places')body=Object.entries(P).map(([id,n])=>`<div class="entry"><strong>${n}</strong><small>${S.visited.includes(id)?'VISITED':'UNSEEN'}</small><p>${id==='shop'?'A snug room of found things and lamplight.':id==='street'?'The narrow lane between the shop and station.':id==='station'?'An old platform where the 8:17 once waited.':'A repair shop warm as a pocket.'}</p></div>`).join('');if(tab==='Notes')body=`<div class="entry"><strong>The Watch That Waited</strong><small>${S.ending?'RESOLVED':'IN PROGRESS'}</small><p>${S.ending?'Some stories do not undo the years. They make room for a kinder telling.':`You have ${S.clues.length} of 5 pieces. A stopped watch, an old friendship, and a missed train.`}</p></div>`;panel(`<div class="panel-kicker">A POCKET-SIZED RECORD</div><h2>The Journal</h2><p class="lead">Little details have a way of finding one another.</p><div class="tabs">${tabs.map(t=>`<button class="tab ${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div>${body}<div class="btn-row"><button class="action secondary" data-a="board">Open clue board</button><button class="action secondary" data-a="inventory">Pocket inventory</button></div>`,true)}
14: function inventory(){let list=S.clues.map(id=>C[id]);panel(`<div class="panel-kicker">WHAT YOU’VE FOUND</div><h2>Your pockets</h2><p class="lead">A careful keeper makes room for small things.</p>${list.length?`<div class="grid">${list.map(c=>`<div class="card"><div class="glyph">${c[0]}</div><strong>${c[1]}</strong><small>${c[2]}</small></div>`).join('')}</div>`:'<p>Nothing yet. The watch is waiting on the counter.</p>'}<div class="divider"></div><button class="action secondary" data-a="journal">Back to journal</button>`)}
15: function board(){let found=S.clues.filter(x=>['watch','photo','timetable','mechanism','letter'].includes(x));panel(`<div class="panel-kicker">PIN THE FRAGMENTS TOGETHER</div><h2>The clue board</h2><p class="lead">Choose two details to see what they might share. The town will not solve it for you.</p>${found.length<2?`<p>You need two pieces before a pattern can emerge. You have ${found.length}.</p>`:`<div class="clue-board">${found.map(id=>`<button class="clue-node ${S.pick===id?'selected':''}" data-pick="${id}"><strong>${C[id][0]} ${C[id][1]}</strong><small>${C[id][2]}</small></button>`).join('')}<div class="board-link">↔</div><div style="grid-column:1/-1;text-align:center;color:#8c8d7b;font-size:10px">${S.pick?'Choose another clue to compare':'Select a clue, then another'}</div></div><div class="btn-row"><button class="action gold" data-a="connect">Connect these clues</button></div>`}${S.clues.includes('photo')&&S.clues.includes('timetable')?'<div class="entry"><strong>✦ A plan, not a coincidence</strong><p>The photograph and timetable both point to the 8:17. June and Elias intended to leave together.</p></div>':''}${S.clues.includes('letter')?'<div class="entry"><strong>✦ Silence kept in a small case</strong><p>The watch was deliberately stopped. Its hidden letter explains why Elias stayed — and why he never returned.</p></div>':''}<div class="divider"></div><button class="action secondary" data-a="journal">Back to journal</button>`,true)}
